app:
/* ========== أسماء جهات الاتصال للتاب — إضافة 2026-11 ==========
 * التاب يحفظ أي رقم يدزله بجهات الاتصال باسمه الصحيح (أأمن لواتساب).
 * المصدر: مندوبات الانفو والمشرفات (قاعدة بيانات اللوحة) + الأشخاص بالدليل.
 */
const CONTACTS_KEY = 'ck_ecab6e1b5e7d92603cf06db7';
const CONTACTS_FIX = { '7726948905': 'دعاوي (دعاء جواد) | اشتري اونلاين', '7731033966': 'سرى عبد حمزة | لؤلؤ للاكسسوارات', '7702534506': 'علا عبد حمزة | اكسسوارات نسائية' };

function phone10_(p) { let d = String(p || '').replace(/\D/g, ''); if (d.indexOf('964') === 0) d = d.slice(3); if (d[0] === '0') d = d.slice(1); return /^7\d{9}$/.test(d) ? d : ''; }

function contactsMap_() {
  const cache = CacheService.getScriptCache(), hit = cache.get('CONTACTS_MAP');
  if (hit) return JSON.parse(hit);
  const map = {};
  try {
    const r = UrlFetchApp.fetch(SUPA.URL + '/rest/v1/rpc/contacts_export', { method: 'post', contentType: 'application/json', muteHttpExceptions: true,
      headers: { apikey: SUPA.KEY, Authorization: 'Bearer ' + SUPA.KEY }, payload: JSON.stringify({ p_key: CONTACTS_KEY }) });
    const j = JSON.parse(r.getContentText());
    (j.rows || []).forEach(x => {
      const ph = phone10_(x.ph); if (!ph) return;
      const nm = String(x.nm || '').split(' / ').pop().trim(), pg = String(x.pg || '').split(' / ')[0].replace('الادارة الثانوية', 'الإدارة').trim();
      if (!nm) return;
      if (pg === 'مشرفة' || !map[ph]) map[ph] = nm + ' | ' + pg;
    });
  } catch (e) { console.warn('contacts: ' + e); }
  const dir = loadDirectory_();
  Object.keys(dir).forEach(name => { const d = dir[name]; if (d.type === 'شخص') { const ph = phone10_(d.target); if (ph && !map[ph]) map[ph] = name; } });
  Object.keys(CONTACTS_FIX).forEach(k => map[k] = CONTACTS_FIX[k]);
  cache.put('CONTACTS_MAP', JSON.stringify(map), 21600);
  return map;
}

function contactName_(target) { const ph = phone10_(target); return ph ? (contactsMap_()[ph] || '') : ''; }

// body: {action:'contacts', device}
function contacts_(b) {
  const sender = touchSender_(b.device);
  if (!sender) return { ok: false, error: 'جهاز غير معروف' };
  const m = contactsMap_();
  return { ok: true, contacts: Object.keys(m).map(k => ({ phone: '0' + k, name: m[k] })) };
}
